  assert.match(text, /€1,200\.00/);
});

test('renderInvoiceText shows correct total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
